// Historical market data and derived series.
//
// Source: monthly total returns (dividends reinvested) of VFINX (S&P 500) and
// VBMFX (US total bond market), generated by scripts/fetch-market-history.mjs.
// Stock and bond returns are paired by month, so a mixed portfolio's history
// keeps the real correlation between the two.

import data from '../data/marketHistory.json';

export const MARKET = data;

const seriesCache = new Map();

/** Monthly returns of a portfolio rebalanced monthly to `stockPct` stocks / rest bonds. */
export function portfolioSeries(stockPct) {
  const w = Math.min(1, Math.max(0, stockPct));
  const key = Math.round(w * 1000);
  if (!seriesCache.has(key)) {
    const out = new Float64Array(data.months.length);
    for (let i = 0; i < out.length; i++) {
      out[i] = w * data.stocks[i] + (1 - w) * data.bonds[i];
    }
    seriesCache.set(key, out);
  }
  return seriesCache.get(key);
}

export function seriesStats(series) {
  const n = series.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += series[i];
  const mean = sum / n;
  let m2 = 0, m4 = 0;
  for (let i = 0; i < n; i++) {
    const d = series[i] - mean;
    m2 += d * d;
    m4 += d * d * d * d;
  }
  const variance = m2 / n;
  return {
    mean,
    sd: Math.sqrt(m2 / (n - 1)),
    // Excess kurtosis: 0 for a normal distribution; > 0 means fatter tails.
    excessKurtosis: m4 / n / (variance * variance) - 3,
  };
}

/** Real, data-derived facts about how a stock/bond mix has actually behaved. */
export function historicalSummary(stockPct) {
  const s = portfolioSeries(stockPct);
  const months = data.months;
  const n = s.length;

  let growth = 1;
  for (let i = 0; i < n; i++) growth *= 1 + s[i];
  const years = n / 12;

  // Rolling 12-month returns
  let worst12 = { ret: Infinity, end: null };
  let best12 = { ret: -Infinity, end: null };
  for (let i = 11; i < n; i++) {
    let g = 1;
    for (let k = i - 11; k <= i; k++) g *= 1 + s[k];
    const r = g - 1;
    if (r < worst12.ret) worst12 = { ret: r, end: months[i] };
    if (r > best12.ret) best12 = { ret: r, end: months[i] };
  }

  // Maximum peak-to-trough drawdown
  let idx = 1, peak = 1, peakAt = months[0];
  let maxDD = { dd: 0, peak: null, trough: null };
  for (let i = 0; i < n; i++) {
    idx *= 1 + s[i];
    if (idx > peak) { peak = idx; peakAt = months[i]; }
    const dd = 1 - idx / peak;
    if (dd > maxDD.dd) maxDD = { dd, peak: peakAt, trough: months[i] };
  }

  const { sd, excessKurtosis } = seriesStats(s);
  return {
    start: data.start,
    end: data.end,
    years,
    annualReturn: Math.pow(growth, 1 / years) - 1,
    annualVol: sd * Math.sqrt(12),
    worst12,
    best12,
    maxDrawdown: maxDD,
    excessKurtosis,
  };
}

// Real historical crash windows, replayed month-by-month in stress tests.
export const STRESS_SCENARIOS = [
  { id: '2008', label: '2008 financial crisis', short: '2008', start: '2007-11', end: '2009-02' },
  { id: '2000', label: 'Dot-com bust',          short: '2000', start: '2000-09', end: '2002-09' },
  { id: '2020', label: 'COVID crash',           short: '2020', start: '2020-02', end: '2020-03' },
  { id: '2022', label: '2022 rate shock',       short: '2022', start: '2022-01', end: '2022-09' },
  { id: '1987', label: 'Black Monday (1987)',   short: '1987', start: '1987-09', end: '1987-11' },
];

export function stressReturns(id, stockPct) {
  const sc = STRESS_SCENARIOS.find(x => x.id === id);
  if (!sc) return null;
  const i0 = data.months.indexOf(sc.start);
  const i1 = data.months.indexOf(sc.end);
  if (i0 < 0 || i1 < i0) return null;
  return portfolioSeries(stockPct).slice(i0, i1 + 1);
}

/** Cumulative return of a portfolio through a stress window, e.g. -0.42. */
export function stressImpact(id, stockPct) {
  const r = stressReturns(id, stockPct);
  if (!r) return null;
  let g = 1;
  for (const x of r) g *= 1 + x;
  return { ret: g - 1, months: r.length };
}
